package com.milktea.auth.service.impl;
import com.milktea.auth.dto.*; import com.milktea.auth.service.AuthService; import com.milktea.common.exception.BusinessException; import com.milktea.security.*; import com.milktea.user.entity.*; import com.milktea.user.repository.*; import java.time.Duration; import java.time.Instant; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthServiceImpl implements AuthService { private final NguoiDungRepository users; private final VaiTroRepository roles; private final PasswordEncoder encoder; private final JwtService jwt; private final StringRedisTemplate redis; private final Duration refreshTtl; public AuthServiceImpl(NguoiDungRepository users,VaiTroRepository roles,PasswordEncoder encoder,JwtService jwt,StringRedisTemplate redis,@Value("${app.jwt.refresh-token-days}") long days){this.users=users;this.roles=roles;this.encoder=encoder;this.jwt=jwt;this.redis=redis;this.refreshTtl=Duration.ofDays(days);} public AuthResponse login(LoginRequest r){NguoiDung u=users.findByTenDangNhap(r.username()).orElseThrow(()->new BusinessException(HttpStatus.UNAUTHORIZED,"Sai tên đăng nhập hoặc mật khẩu"));if(!u.isDangHoatDong()||!encoder.matches(r.password(),u.getMatKhauMaHoa()))throw new BusinessException(HttpStatus.UNAUTHORIZED,"Sai tên đăng nhập hoặc mật khẩu");return tokens(UserPrincipal.from(u));} public AuthResponse register(RegisterRequest r){if(users.existsByTenDangNhap(r.username()))throw new BusinessException(HttpStatus.CONFLICT,"Tên đăng nhập đã tồn tại");VaiTro role=roles.findByTenVaiTro("CUSTOMER").orElseThrow(()->new BusinessException(HttpStatus.INTERNAL_SERVER_ERROR,"Thiếu role CUSTOMER"));NguoiDung u=new NguoiDung();u.setVaiTro(role);u.setTenDangNhap(r.username());u.setMatKhauMaHoa(encoder.encode(r.password()));u.setHoVaTen(r.fullName());u.setSoDienThoai(r.phone());u.setDangHoatDong(true);u.setNgayTao(Instant.now());return tokens(UserPrincipal.from(users.save(u)));} public AuthResponse refresh(RefreshRequest r){if(!jwt.isRefresh(r.refreshToken())||!Boolean.TRUE.equals(redis.hasKey(key(r.refreshToken()))))throw new BusinessException(HttpStatus.UNAUTHORIZED,"Refresh token không hợp lệ");String username=jwt.claims(r.refreshToken()).getSubject();NguoiDung u=users.findByTenDangNhap(username).orElseThrow(()->new BusinessException(HttpStatus.UNAUTHORIZED,"Người dùng không tồn tại"));redis.delete(key(r.refreshToken()));return tokens(UserPrincipal.from(u));} public void logout(String token){if(token!=null)redis.delete(key(token));} public MeResponse me(UserPrincipal p){NguoiDung u=users.findWithVaiTroById(p.id()).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Không tìm thấy người dùng"));return new MeResponse(u.getId(),u.getTenDangNhap(),u.getHoVaTen(),u.getVaiTro().getTenVaiTro());} private AuthResponse tokens(UserPrincipal p){String refresh=jwt.refreshToken(p);redis.opsForValue().set(key(refresh),p.username(),refreshTtl);return new AuthResponse(jwt.accessToken(p),refresh,"Bearer");} private String key(String t){return "auth:refresh:"+t;} }
